from shop import Inventory
from shop.report import reserved_units


def example():
    inventory = Inventory({'mug': 8})
    inventory.reserve('mug', 3)
    return inventory.available['mug'], reserved_units(inventory, 'mug')


if __name__ == '__main__':
    print(example())

